 if(!result)return OCCTSHARP_STATUS_INVALID_ARGUMENT;*result=nullptr;
 return Guard([&]{auto workspace=OcctSharpOwned::Lease<const Workspace>(token);
  if(selector==0)*result=CopyKeys(workspace->viewSmall);else if(selector==1)*result=CopyKeys(workspace->viewMultiple);
  else if(selector==2)*result=CopyKeys(workspace->viewEdgeFaces);else if(selector==3)*result=CopyKeys(workspace->viewFaceSmall);
  else if(selector==4)*result=PublishValues(workspace->viewShapes);
  else{Require(selector==5 || selector==6,"Unknown workspace collection.");const auto& map=selector==5?workspace->viewEdgeFaces:workspace->viewFaceSmall;
   Require(index>=0 && index<map.Extent(),"Map entry index outside bounds.");int n=0;for(ShapeMap::Iterator it(map);it.More();it.Next(),++n)if(n==index){*result=PublishShapes(it.Value());break;}}});
